import json
from pathlib import Path
CASES=[]
def add(lang,level,kind,text,target,*spoken):
 assert text.count(target)==1,(text,target)
 CASES.append(dict(id=f'{lang.upper()}-{sum(c["lang"]==lang for c in CASES)+1:03}',lang=lang,level=level,kind=kind,text=text,target=target,expected=[text.replace(target,s) for s in spoken]))
